python3 << 'EOF'
import subprocess, re, os

flagged = ["src/app/api/email/new.tsx","src/components/ImageConfetti.jsx","src/components/ProfileEmailCard.tsx","src/components/SquareImage.tsx","src/components/email.tsx","src/components/experience.tsx","src/components/helpers/commitHash.tsx","src/components/ui/accordion.tsx","src/components/ui/card.tsx","src/components/ui/input.tsx","src/components/ui/tooltip.tsx","src/lib/experience.ts","src/lib/interfaces.ts"]

# 1. Who imports each flagged file? (search by basename, exclude the flagged files themselves)
out = subprocess.run(["grep","-rn","--include=*.ts","--include=*.tsx","--include=*.js","--include=*.jsx","-E","import|require","src/"],capture_output=True,text=True).stdout.splitlines()
for f in flagged:
    base = os.path.splitext(os.path.basename(f))[0]
    hits = [l for l in out if re.search(r'''["'/]''' + re.escape(base) + r'''["']''', l) and not any(l.startswith(g+":") for g in flagged)]
    print(f, "-> imported by:", hits if hits else "NOBODY")

print("\n--- external packages imported by flagged files ---")
pkgs = {}
for f in flagged:
    for line in open(f):
        m = re.search(r'''from\s+["']([^."'][^"']*)["']|import\s+["']([^."'][^"']*)["']''', line)
        if m:
            p = m.group(1) or m.group(2)
            if not p.startswith("@/"):
                pkgs.setdefault(p, set()).add(f)
for p, fs in sorted(pkgs.items()):
    # is this pkg imported by any NON-flagged file?
    others = [l for l in out if re.search(r'''["']''' + re.escape(p) + r'''["']''', l) and not any(l.startswith(g+":") for g in flagged)]
    print(p, "| flagged users:", len(fs), "| used elsewhere:", "YES" if others else "NO")
EOF

